contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address target) public {
        require(target != address(c));
        require(target != address(this));

        uint balBefore = address(c).balance;
        uint countBefore = c.depositsCount(); if (__ESBMC_reverted()) return;

        c.sendMoney(target, 0, ""); if (__ESBMC_reverted()) return;

        uint balAfter = address(c).balance;
        uint countAfter = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(balAfter == balBefore && countAfter == countBefore);
    }

    receive() external payable {}
}

